from collections import Counter
def regions(cells):
    cells=set(cells); seen=set(); regs=[]
    for c in cells:
        if c in seen: continue
        st=[c]; comp=set()
        while st:
            x=st.pop()
            if x in comp: continue
            comp.add(x); seen.add(x)
            a,b=x
            for da in(-1,0,1):
                for db in(-1,0,1):
                    n=(a+da,b+db)
                    if n in cells and n not in comp: st.append(n)
        regs.append(comp)
    return regs
def solve2(inp):
    h,w=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    noise={c for c in cnt if c not in (0,1,4)}
    # build regions for non-noise colors
    cellmap={}
    regs=[]
    for c in cnt:
        if c in noise: continue
        rs=[(i,j) for i in range(h) for j in range(w) if inp[i][j]==c]
        regs+= [(c,reg) for reg in regions(rs)]
    out=[r[:] for r in inp]
    for i in range(h):
        for j in range(w):
            if inp[i][j] in noise:
                best=None
                for c,reg in regs:
                    rs={(a,b) for a,b in reg}|{(i,j)}
                    ia=min(a for a,b in rs); ib=min(b for a,b in rs)
                    xa=max(a for a,b in rs); xb=max(b for a,b in rs)
                    if (xa-ia+1)*(xb-ib+1)==len(rs) and (ia,ib,xa,xb)==(min(a for a,b in reg),min(b for a,b in reg),max(a for a,b in reg),max(b for a,b in reg)):
                        best=c
                out[i][j]=best if best is not None else inp and noise_background(inp,i,j)
    return out
def noise_background(inp,i,j): return inp[i][j]
